-- Définitions du glossaire réécrites : ce qu'est la plante, comment on la mange, ce qui la rend particulière
update public.species set description='Fruit-légume emblématique de l''été, à chair juteuse, de la grosse tomate à farcir à la variété ancienne colorée. Se mange crue, en sauce ou séchée.' where slug='tomate';
update public.species set description='Tomate à petits fruits sucrés et très parfumés, produits en grappes tout l''été et à grignoter crus. La plus facile et la plus généreuse des tomates.' where slug='tomate-cerise';
update public.species set description='Fruit creux à chair épaisse et douce, vert avant maturité puis rouge, jaune ou orange et plus sucré. Se mange cru, farci ou grillé ; il aime la chaleur.' where slug='poivron';
update public.species set description='Petit fruit allongé ou rond, du doux au très fort, qui relève les plats frais ou séchés. Plus la variété est piquante, plus elle a besoin de chaleur.' where slug='piment';
update public.species set description='Fruit à peau lisse violette et chair fondante, incontournable des ratatouilles, gratins et caviars. Exigeante en chaleur, elle demande une longue saison.' where slug='aubergine';
update public.species set description='Fruit allongé cueilli jeune et tendre, à cuisiner en gratin, poêlé ou cru en lamelles ; ses fleurs se mangent aussi. Un seul pied nourrit une famille tout l''été.' where slug='courgette';
update public.species set description='Fruit allongé très aqueux, croquant et rafraîchissant, mangé cru en salade ou en tzatziki, ou en cornichon quand il est petit. Plante grimpante qui aime la chaleur et l''eau.' where slug='concombre';
update public.species set description='Gros fruit à chair dense et sucrée (potimarron, butternut, potiron…), pour soupes, purées et gratins, qui se conserve tout l''hiver. Plante coureuse très gourmande en place.' where slug='courge';
update public.species set description='Fruit sucré et très parfumé à chair orangée, à déguster frais en été. Réussit au nord de la Loire sous cloche ou tunnel.' where slug='melon';
update public.species set description='Très gros fruit à chair rouge, juteuse et rafraîchissante. Réclame beaucoup de chaleur, de soleil et de place.' where slug='pasteque';
update public.species set description='Céréale cultivée pour ses épis : le maïs doux se mange jeune, grillé ou bouilli, sucré et tendre. Haute et décorative, elle sert de tuteur aux haricots.' where slug='mais';
update public.species set description='Légumineuse buissonnante dont on mange les gousses vertes (haricot vert) ou les graines. Productif et sans tuteur, à semer en plusieurs fois.' where slug='haricot-nain';
update public.species set description='Haricot grimpant à tuteurer, dont les longues gousses se récoltent pendant des semaines. Plus productif que le haricot nain à surface égale.' where slug='haricot-a-rames';
update public.species set description='Graines sucrées enfermées dans des cosses vertes, à écosser et manger fraîches au printemps. Plante grimpante qui enrichit le sol en azote.' where slug='petit-pois';
update public.species set description='Grosse graine verte, tendre et légèrement amère, mangée fraîche ou séchée. Légumineuse très rustique qui se sème à l''automne ou en fin d''hiver.' where slug='feve';
update public.species set description='Racine orange, sucrée et croquante, mangée crue, râpée ou cuite. Se cultive en sol léger et sans cailloux, avec des semis réguliers.' where slug='carotte';
update public.species set description='Petite racine rouge ou rose, croquante et piquante, qu''on croque à l''apéritif. Prêt en un mois : idéal pour débuter.' where slug='radis';
update public.species set description='Racine rouge ou jaune à saveur sucrée et terreuse, mangée cuite ou crue râpée ; les feuilles se cuisinent comme des blettes.' where slug='betterave';
update public.species set description='Racine ronde blanche ou violette à chair douce et légèrement piquante, du potage au pot-au-feu. Se cultive au frais, au printemps et à l''automne.' where slug='navet';
update public.species set description='Racine blanche proche de la carotte, à la saveur douce et noisettée, en purée, en soupe ou rôtie. Supporte très bien le gel.' where slug='panais';
update public.species set description='Grosse racine ronde au goût de céleri, mangée crue râpée en rémoulade ou cuite en purée et en soupe. Se conserve longtemps.' where slug='celeri-rave';
update public.species set description='Tubercule féculent de base de l''alimentation, aux variétés précoces ou de garde, en vapeur, purée ou frites. Se plante à partir de plants germés.' where slug='pomme-de-terre';
update public.species set description='Tubercule vivace à saveur d''artichaut, mangé cuit en purée ou en soupe. Pousse sans entretien mais devient vite envahissant.' where slug='topinambour';
update public.species set description='Bulbe formé de gousses à saveur forte, base de la cuisine et protecteur de nombreux voisins. Se plante à l''automne ou à la fin de l''hiver.' where slug='ail';
update public.species set description='Bulbe à saveur piquante cru et douce cuit, de la salade à la soupe. Se conserve plusieurs mois une fois séché.' where slug='oignon';
update public.species set description='Petit bulbe plus fin et plus parfumé que l''oignon, indispensable aux sauces et vinaigrettes. Un seul bulbe en donne plusieurs.' where slug='echalote';
update public.species set description='Légume à long fût blanc et feuilles vertes, doux et fondant en potage, vinaigrette ou gratin. Très rustique, il se récolte tout l''hiver.' where slug='poireau';
update public.species set description='Feuilles tendres de laitue, batavia ou feuille de chêne, base des salades fraîches. Pousse vite mais monte à graines par forte chaleur.' where slug='salade';
update public.species set description='Petites rosettes de feuilles douces et légèrement noisettées qui supportent le gel : la salade de l''hiver.' where slug='mache';
update public.species set description='Feuilles vertes tendres, riches en fer et en vitamines, mangées crues en jeunes pousses ou cuites. Préfère le frais et monte à graines en été.' where slug='epinard';
update public.species set description='Grandes feuilles vertes à larges côtes blanches, cuisinées comme l''épinard ou le chou. Productive de l''été à l''hiver, elle repousse après chaque coupe.' where slug='blette';
update public.species set description='Feuilles découpées au goût poivré et légèrement piquant, en salade ou sur une pizza. Prête en quatre semaines.' where slug='roquette';
update public.species set description='Feuilles vertes à saveur acidulée et citronnée, pour soupes, sauces et poissons. Vivace : elle revient chaque année.' where slug='oseille';
update public.species set description='Légume à pomme serrée de feuilles (cabus, rouge, frisé de Milan), cru en salade ou cuit en soupe, potée ou choucroute. Très rustique, il fournit l''hiver.' where slug='chou';
update public.species set description='Chou dont on mange les têtes vertes de boutons floraux, cuites à la vapeur ou crues. Après la tête centrale, la plante donne des rejets.' where slug='brocoli';
update public.species set description='Chou dont on mange la grosse pomme blanche de fleurs compactes, en gratin, en soupe ou cru. Plus délicat à cultiver, il demande de la régularité.' where slug='chou-fleur';
update public.species set description='Chou non pommé aux feuilles frisées, très riches en vitamines, récolté feuille à feuille. Il résiste au gel et devient plus doux avec le froid.' where slug='kale';
update public.species set description='Chou dont la tige se renfle en boule blanche ou violette, croquante et douce, mangée crue ou cuite.' where slug='chou-rave';
update public.species set description='Chou asiatique aux larges côtes blanches et aux feuilles vertes tendres, sauté au wok ou en soupe. Pousse très vite.' where slug='pak-choi';
update public.species set description='Pousses tendres (turions) vertes ou blanches, légume de luxe du printemps. Vivace qui produit une dizaine d''années après une installation patiente.' where slug='asperge';
update public.species set description='Grande vivace dont on mange le fond et les bractées charnues du capitule, cuit à l''eau ou à la vapeur. Décorative, elle donne de grandes fleurs violettes.' where slug='artichaut';
update public.species set description='Plante vivace dont on mange les gros pétioles rouges ou verts, acidulés, en compote, tarte ou confiture. Les feuilles sont toxiques.' where slug='rhubarbe';
update public.species set description='Légume à bulbe croquant au goût d''anis, cru en salade ou cuit au four ou braisé. À semer après le solstice pour éviter la montée à graines.' where slug='fenouil';
update public.species set description='Herbe aromatique aux feuilles tendres et très parfumées, indispensable au pesto, à la salade de tomates et aux pâtes. Craint le froid.' where slug='basilic';
update public.species set description='Herbe aromatique de base, plat ou frisé, qui parfume sauces, salades et marinades. Riche en vitamine C, il se récolte presque toute l''année.' where slug='persil';
update public.species set description='Herbe vivace à fines tiges creuses au goût d''oignon doux, qui relève œufs, salades et fromages blancs. Ses fleurs roses sont comestibles.' where slug='ciboulette';
update public.species set description='Herbe aromatique à fines feuilles plumeuses au goût anisé, idéale avec le poisson, les cornichons et les yaourts.' where slug='aneth';
update public.species set description='Herbe aromatique aux feuilles fraîches et très parfumées, de la cuisine asiatique et orientale ; ses graines sont un condiment. Monte vite à graines.' where slug='coriandre';
update public.species set description='Herbe vivace très parfumée et rafraîchissante, pour tisanes, boissons et plats d''été. Vigoureuse et envahissante : à garder en pot.' where slug='menthe';
update public.species set description='Petit arbrisseau aromatique vivace aux feuilles minuscules, qui parfume viandes, légumes et marinades. Rustique et résistant à la sécheresse.' where slug='thym';
update public.species set description='Arbuste persistant aux feuilles en aiguilles, au parfum puissant, pour viandes grillées et légumes rôtis. Mellifère et résistant à la sécheresse.' where slug='romarin';
update public.species set description='Sous-arbrisseau aux feuilles veloutées gris-vert, au goût marqué, pour la cuisine et les tisanes. Ses fleurs violettes attirent les abeilles.' where slug='sauge';
update public.species set description='Fleur orange ou jaune aux feuilles rondes et au goût poivré, qui se mange en salade. Elle attire les pucerons à sa place et protège les légumes voisins.' where slug='capucine';
update public.species set description='Petite fleur jaune ou orangée à odeur marquée, plantée au potager pour éloigner nématodes et aleurodes, surtout près des tomates.' where slug='oeillet-d-inde';
update public.species set description='Fleur orange vif comestible dont les pétales colorent salades et plats, utile pour le sol et les pollinisateurs. Se ressème toute seule.' where slug='souci';
update public.species set description='Grande fleur jaune qui suit le soleil, aux graines comestibles, très appréciée des pollinisateurs. Sert aussi de tuteur naturel aux plantes grimpantes.' where slug='tournesol';
update public.species set description='Petit fruit rouge parfumé et sucré, qui donne des stolons pour se multiplier. Vivace productive pendant trois à quatre ans.' where slug='fraise';
update public.species set description='Arbuste à cannes qui produit des framboises sucrées et parfumées en été (ou à l''automne selon les variétés), à manger fraîches ou en confiture.' where slug='framboisier';
update public.species set description='Arbuste rustique aux grappes de petits fruits rouges, blancs ou noirs (cassis), acidulés et riches en vitamine C, pour gelées et desserts.' where slug='groseillier';
update public.species set description='Arbuste à baies bleues sucrées-acidulées, riches en antioxydants. Exigeante : elle réclame un sol acide, comme la terre de bruyère.' where slug='myrtille';
